41	    __aicore__ inline void ProcessGatherPath(int64_t startRow, int64_t numRows);
42	    __aicore__ inline void ProcessUBPath(int64_t row);
43	    __aicore__ inline void ProcessElementPath(int64_t row);
44	
45	    __aicore__ inline void LoadIndexForRow(int64_t row, LocalTensor<int32_t> &indexLocal)
46	    {
47	        DataCopyExtParams params;
48	        params.blockCount = 1;
49	        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
50	        params.srcStride = 0;
51	        params.dstStride = 0;
52	        DataCopyPadExtParams<int32_t> padParams;
53	        padParams.isPad = false;
54	        DataCopyPad(indexLocal, indexGm[row * indexSize_], params, padParams);
55	        PipeBarrier<PIPE_ALL>();
56	    }
57	
58	    __aicore__ inline void WriteOutputForRow(int64_t row, LocalTensor<T> &outputLocal)
59	    {
60	        DataCopyExtParams params;
61	        params.blockCount = 1;
62	        params.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
63	        params.srcStride = 0;
64	        params.dstStride = 0;
65	        DataCopyPad(outputGm[row * indexSize_], outputLocal, params);
66	        PipeBarrier<PIPE_ALL>();
67	    }
