// ============================================================
// EmbeddingDenseGradV2 op_kernel
// 算子: scatter-add 梯度累加 (EmbeddingDenseBackward)
// 分核模式 C: AtomicAdd 原子累加
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

template <typename T>
class EmbeddingDenseGradV2AccumulateKernel {
public:
    __aicore__ inline EmbeddingDenseGradV2AccumulateKernel() {}

    __aicore__ inline void Init(GM_ADDR grad, GM_ADDR sortIndices, GM_ADDR posIdx,
                                 GM_ADDR output, int64_t totalPositions,
                                 int64_t embeddingDim, int64_t numWeights,
                                 int64_t paddingIdx, int64_t scaleGradByFreq,
                                 int64_t formerNum, int64_t formerLength,
                                 int64_t tailNum, int64_t tailLength,
                                 int64_t tileLength, int64_t dtypeSize,
                                 int64_t embDimAligned, int64_t totalLengthCoreAlign);
    __aicore__ inline void Process();

private:
    TPipe pipe;

    // Index buffers (int32, single buffer - sequential access)
    TBuf<TPosition::VECIN> sortIdxBuf;
    TBuf<TPosition::VECIN> posIdxBuf;

    // Grad row buffers
    TBuf<TPosition::VECIN> gradRowBuf;

    // FP32 workspace for fp16/bf16 computation (only used in scale kernel, not needed here)
    // For accumulate, we just do raw AtomicAdd with the input dtype

    GlobalTensor<T> gradGm;
    GlobalTensor<int32_t> sortIndicesGm;
    GlobalTensor<int32_t> posIdxGm;
    GlobalTensor<T> outputGm;

    int64_t totalPositions_ = 0;
    int64_t embeddingDim_ = 0;
    int64_t numWeights_ = 0;
    int64_t paddingIdx_ = 0;
    int64_t scaleGradByFreq_ = 0;

    // Block-level
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
    int64_t totalLengthCoreAlign_ = 0;

    // UB-level
    int64_t tileLength_ = 0;
    int64_t dtypeSize_ = 0;
    int64_t embDimAligned_ = 0;
    int64_t alignedTileLength_ = 0;
};

template <typename T>
__aicore__ inline void EmbeddingDenseGradV2AccumulateKernel<T>::Init(
        GM_ADDR grad, GM_ADDR sortIndices, GM_ADDR posIdx,
        GM_ADDR output, int64_t totalPositions,
        int64_t embeddingDim, int64_t numWeights,
        int64_t paddingIdx, int64_t scaleGradByFreq,
        int64_t formerNum, int64_t formerLength,
        int64_t tailNum, int64_t tailLength,
        int64_t tileLength, int64_t dtypeSize,
        int64_t embDimAligned, int64_t totalLengthCoreAlign) {
    totalPositions_ = totalPositions;
    embeddingDim_ = embeddingDim;
    numWeights_ = numWeights;
    paddingIdx_ = paddingIdx;
    scaleGradByFreq_ = scaleGradByFreq;
    formerNum_ = formerNum;
    formerLength_ = formerLength;
    tailNum_ = tailNum;
    tailLength_ = tailLength;
    totalLengthCoreAlign_ = totalLengthCoreAlign;
    tileLength_ = tileLength;
    dtypeSize_ = dtypeSize;
    embDimAligned_ = embDimAligned;

    // Align tileLength to 8 elements (32 bytes for int32)
    alignedTileLength_ = ((tileLength_ + 7) / 8) * 8;

    gradGm.SetGlobalBuffer((__gm__ T*)grad);
    sortIndicesGm.SetGlobalBuffer((__gm__ int32_t*)sortIndices);
    posIdxGm.SetGlobalBuffer((__gm__ int32_t*)posIdx);
    outputGm.SetGlobalBuffer((__gm__ T*)output);

    // UB allocation
    pipe.InitBuffer(sortIdxBuf, alignedTileLength_ * sizeof(int32_t));
    pipe.InitBuffer(posIdxBuf, alignedTileLength_ * sizeof(int32_t));
    pipe.InitBuffer(gradRowBuf, embDimAligned_ * sizeof(T));
    // No fp32 buf needed - accumulate does raw dtype AtomicAdd
}

template <typename T>
__aicore__ inline void EmbeddingDenseGradV2AccumulateKernel<T>::Process() {
    int64_t blockIdx = GetBlockIdx();

    // Compute this core's assigned position range
    int64_t coreStart, coreLength;
    if (totalLengthCoreAlign_ <= 0) return;

    if (blockIdx < formerNum_) {
        coreStart = blockIdx * formerLength_;
        coreLength = formerLength_;
    } else if (blockIdx == formerNum_) {
        coreStart = formerNum_ * formerLength_;
        coreLength = tailLength_;
    } else {
        return;
    }
    if (coreLength <= 0) return;

    // Cap to total positions
    if (coreStart >= totalPositions_) return;
    if (coreStart + coreLength > totalPositions_) {
        coreLength = totalPositions_ - coreStart;
    }

    LocalTensor<int32_t> sortIdxLocal = sortIdxBuf.Get<int32_t>();
    LocalTensor<int32_t> posIdxLocal = posIdxBuf.Get<int32_t>();
    LocalTensor<T> gradRowLocal = gradRowBuf.Get<T>();

    int64_t pos = coreStart;
    int64_t remaining = coreLength;

    while (remaining > 0) {
        int64_t curLen = remaining < tileLength_ ? remaining : tileLength_;
        if (curLen <= 0) break;

        // CopyIn: load sort_indices and pos_idx tiles
        DataCopyExtParams idxCopyParams;
        idxCopyParams.blockCount = 1;
        idxCopyParams.blockLen = static_cast<uint32_t>(curLen * sizeof(int32_t));
        idxCopyParams.srcStride = 0;
        idxCopyParams.dstStride = 0;

        DataCopyPadExtParams<int32_t> idxPadParams;
        idxPadParams.isPad = false;

        DataCopyPad(sortIdxLocal, sortIndicesGm[pos], idxCopyParams, idxPadParams);
        PipeBarrier<PIPE_ALL>();

        DataCopyPad(posIdxLocal, posIdxGm[pos], idxCopyParams, idxPadParams);
        PipeBarrier<PIPE_ALL>();

        // Compute: for each position, atomic-add grad row to output
        DataCopyExtParams gradParams;
        gradParams.blockCount = 1;
        gradParams.blockLen = static_cast<uint32_t>(embeddingDim_ * sizeof(T));
        gradParams.srcStride = 0;
        gradParams.dstStride = 0;

        DataCopyPadExtParams<T> gradPadParams;
        gradPadParams.isPad = false;

        for (int64_t p = 0; p < curLen; p++) {
            int32_t weightIdx = sortIdxLocal.GetValue(p);
            if (weightIdx == static_cast<int32_t>(paddingIdx_)) {
                continue;
            }
            if (weightIdx < 0 || weightIdx >= static_cast<int32_t>(numWeights_)) {
                continue;
            }

            int32_t gradPos = posIdxLocal.GetValue(p);
            if (gradPos < 0) continue;

            // Load grad row from GM
            DataCopyPad(gradRowLocal,
                        gradGm[static_cast<int64_t>(gradPos) * embDimAligned_],
                        gradParams, gradPadParams);
            PipeBarrier<PIPE_ALL>();

            // AtomicAdd grad row to output
            SetAtomicAdd<T>();
            DataCopyPad(outputGm[static_cast<int64_t>(weightIdx) * embDimAligned_],
                        gradRowLocal, gradParams);
            SetAtomicNone();
            PipeBarrier<PIPE_ALL>();
        }

        pos += curLen;
        remaining -= curLen;
    }
}

// =========================== Scale Kernel (scale_grad_by_freq) start ============================

template <typename T>
class EmbeddingDenseGradV2ScaleKernel {
public:
    __aicore__ inline EmbeddingDenseGradV2ScaleKernel() {}

    __aicore__ inline void Init(GM_ADDR output, GM_ADDR sortIndices,
                                 int64_t totalPositions, int64_t embeddingDim,
                                 int64_t numWeights, int64_t paddingIdx,
                                 int64_t tileLength, int64_t dtypeSize,
                                 int64_t embDimAligned);
    __aicore__ inline void Process();

private:
    TPipe pipe;

    TBuf<TPosition::VECIN> sortIdxBuf;
    TBuf<TPosition::VECIN> outputRowBuf;

    // FP32 workspace (only for fp16/bf16)
    TBuf<TPosition::VECCALC> outputRowFp32Buf;

    GlobalTensor<T> outputGm;
    GlobalTensor<int32_t> sortIndicesGm;

    int64_t totalPositions_ = 0;
    int64_t embeddingDim_ = 0;
    int64_t numWeights_ = 0;
    int64_t paddingIdx_ = 0;
    int64_t tileLength_ = 0;
    int64_t dtypeSize_ = 0;
    int64_t embDimAligned_ = 0;
    int64_t alignedTileLength_ = 0;

    // Phase 1: freq array (in UB for small numWeights, stored locally)
    // Use a greedy approach: stream through sort_indices, detect runs
};

template <typename T>
__aicore__ inline void EmbeddingDenseGradV2ScaleKernel<T>::Init(
        GM_ADDR output, GM_ADDR sortIndices,
        int64_t totalPositions, int64_t embeddingDim,
        int64_t numWeights, int64_t paddingIdx,
        int64_t tileLength, int64_t dtypeSize,
        int64_t embDimAligned) {
    totalPositions_ = totalPositions;
    embeddingDim_ = embeddingDim;
    numWeights_ = numWeights;
    paddingIdx_ = paddingIdx;
    tileLength_ = tileLength;
    dtypeSize_ = dtypeSize;
    embDimAligned_ = embDimAligned;

    alignedTileLength_ = ((tileLength_ + 7) / 8) * 8;

    outputGm.SetGlobalBuffer((__gm__ T*)output);
    sortIndicesGm.SetGlobalBuffer((__gm__ int32_t*)sortIndices);

    pipe.InitBuffer(sortIdxBuf, alignedTileLength_ * sizeof(int32_t));
    pipe.InitBuffer(outputRowBuf, embDimAligned_ * sizeof(T));

    if constexpr (sizeof(T) != sizeof(float)) {
        pipe.InitBuffer(outputRowFp32Buf, embDimAligned_ * sizeof(float));
    }
}

template <typename T>
__aicore__ inline void EmbeddingDenseGradV2ScaleKernel<T>::Process() {
    // This kernel runs on a single core (blockDim=1)
    // Phase 1: Scan sort_indices to count frequencies (detect runs)
    // Phase 2: For each unique sort_indices value with freq > 1, divide output row

    LocalTensor<int32_t> sortIdxLocal = sortIdxBuf.Get<int32_t>();
    LocalTensor<T> outputRowLocal = outputRowBuf.Get<T>();

    DataCopyExtParams idxCopyParams;
    idxCopyParams.blockCount = 1;
    idxCopyParams.blockLen = 0;  // set per tile
    idxCopyParams.srcStride = 0;
    idxCopyParams.dstStride = 0;

    DataCopyPadExtParams<int32_t> idxPadParams;
    idxPadParams.isPad = false;

    // Streaming run detection
    int32_t prevIdx = -2;  // -2 means "no previous"
    int64_t freqCount = 0;

    for (int64_t p = 0; p < totalPositions_; p += tileLength_) {
        int64_t curLen = totalPositions_ - p;
        if (curLen > tileLength_) curLen = tileLength_;
        if (curLen <= 0) break;

        idxCopyParams.blockLen = static_cast<uint32_t>(curLen * sizeof(int32_t));
        DataCopyPad(sortIdxLocal, sortIndicesGm[p], idxCopyParams, idxPadParams);
        PipeBarrier<PIPE_ALL>();

        for (int64_t i = 0; i < curLen; i++) {
            int32_t idx = sortIdxLocal.GetValue(i);

            if (prevIdx == -2) {
                // First element
                prevIdx = idx;
                freqCount = 1;
                continue;
            }

            if (idx == prevIdx) {
                freqCount++;
            } else {
                // Previous run ended: scale output[prevIdx] if needed
                if (prevIdx != static_cast<int32_t>(paddingIdx_) && freqCount > 1) {
                    ScaleOutputRow(prevIdx, static_cast<int64_t>(freqCount),
                                   outputRowLocal);
                }
                prevIdx = idx;
                freqCount = 1;
            }
        }
    }

    // Handle last run
    if (prevIdx != -2 && prevIdx != static_cast<int32_t>(paddingIdx_) && freqCount > 1) {
        ScaleOutputRow(prevIdx, freqCount, outputRowLocal);
    }
}

template <typename T>
__aicore__ inline void EmbeddingDenseGradV2ScaleKernel<T>::ScaleOutputRow(
        int32_t weightIdx, int64_t freq, LocalTensor<T>& rowLocal) {
    int64_t rowOffset = static_cast<int64_t>(weightIdx) * embDimAligned_;

    DataCopyExtParams rowParams;
    rowParams.blockCount = 1;
    rowParams.blockLen = static_cast<uint32_t>(embeddingDim_ * sizeof(T));
    rowParams.srcStride = 0;
    rowParams.dstStride = 0;

    DataCopyPadExtParams<T> rowPadParams;
    rowPadParams.isPad = false;

    // Load output row
    DataCopyPad(rowLocal, outputGm[rowOffset], rowParams, rowPadParams);
    PipeBarrier<PIPE_ALL>();

    float scale = 1.0f / static_cast<float>(freq);

    if constexpr (sizeof(T) == sizeof(float)) {
        // FP32: direct Muls
        Muls(rowLocal, rowLocal, scale, embeddingDim_);
    } else {
        // FP16/BF16: cast to fp32, compute, cast back
        LocalTensor<float> rowFp32 = outputRowFp32Buf.Get<float>();
        Cast(rowFp32, rowLocal, RoundMode::CAST_NONE, embeddingDim_);
        PipeBarrier<PIPE_ALL>();
        Muls(rowFp32, rowFp32, scale, embeddingDim_);
        PipeBarrier<PIPE_ALL>();
        Cast(rowLocal, rowFp32, RoundMode::CAST_ROUND, embeddingDim_);
        PipeBarrier<PIPE_ALL>();
    }

    // Store output row
    DataCopyPad(outputGm[rowOffset], rowLocal, rowParams);
    PipeBarrier<PIPE_ALL>();
}

// =========================== Kernel entry points start ============================

extern "C" __global__ __aicore__ void embedding_dense_grad_v2_accumulate(
        GM_ADDR grad, GM_ADDR sortIndices, GM_ADDR posIdx,
        GM_ADDR output, int64_t totalPositions,
        int64_t embeddingDim, int64_t numWeights,
        int64_t paddingIdx, int64_t scaleGradByFreq,
        int64_t formerNum, int64_t formerLength,
        int64_t tailNum, int64_t tailLength,
        int64_t tileLength, int64_t dtypeSize,
        int64_t embDimAligned, int64_t totalLengthCoreAlign) {
    if (dtypeSize == 4) {
        EmbeddingDenseGradV2AccumulateKernel<float> op;
        op.Init(grad, sortIndices, posIdx, output, totalPositions,
                embeddingDim, numWeights, paddingIdx, scaleGradByFreq,
                formerNum, formerLength, tailNum, tailLength,
                tileLength, dtypeSize, embDimAligned, totalLengthCoreAlign);
        op.Process();
    } else {
        // fp16 and bf16: both 2 bytes, unified half path
        EmbeddingDenseGradV2AccumulateKernel<half> op;
        op.Init(grad, sortIndices, posIdx, output, totalPositions,
                embeddingDim, numWeights, paddingIdx, scaleGradByFreq,
                formerNum, formerLength, tailNum, tailLength,
                tileLength, dtypeSize, embDimAligned, totalLengthCoreAlign);
        op.Process();
    }
}

extern "C" __global__ __aicore__ void embedding_dense_grad_v2_scale(
        GM_ADDR output, GM_ADDR sortIndices,
        int64_t totalPositions, int64_t embeddingDim,
        int64_t numWeights, int64_t paddingIdx,
        int64_t tileLength, int64_t dtypeSize,
        int64_t embDimAligned) {
    if (dtypeSize == 4) {
        EmbeddingDenseGradV2ScaleKernel<float> op;
        op.Init(output, sortIndices, totalPositions, embeddingDim,
                numWeights, paddingIdx, tileLength, dtypeSize, embDimAligned);
        op.Process();
    } else {
        EmbeddingDenseGradV2ScaleKernel<half> op;
        op.Init(output, sortIndices, totalPositions, embeddingDim,
                numWeights, paddingIdx, tileLength, dtypeSize, embDimAligned);
        op.Process();
    }
}

