// ============================================================
// EmbeddingDenseGradV2 op_host
// 算子: scatter-add 梯度累加 (EmbeddingDenseBackward)
// 分核模式 C: AtomicAdd 原子累加
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_embedding_dense_grad_v2_accumulate.h"
#include "aclrtlaunch_embedding_dense_grad_v2_scale.h"

#include <torch/extension.h>

namespace ascend_kernel {

constexpr int64_t CORE_NUM = 40;
constexpr int64_t CACHE_LINE_BYTES = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;
constexpr int64_t INDEX_BUFFER_COEFF = 8;  // 2 int32 per position = 8 bytes

at::Tensor embedding_dense_grad_v2(
    const at::Tensor& grad,
    const at::Tensor& sort_indices,
    const at::Tensor& pos_idx,
    int64_t num_weights,
    int64_t padding_idx,
    int64_t scale_grad_by_freq) {
    // ---- Input validation ----
    TORCH_CHECK(grad.device().type() == at::DeviceType::PrivateUse1,
                "embedding_dense_grad_v2: grad must be on NPU device");
    TORCH_CHECK(sort_indices.device().type() == at::DeviceType::PrivateUse1,
                "embedding_dense_grad_v2: sort_indices must be on NPU device");
    TORCH_CHECK(pos_idx.device().type() == at::DeviceType::PrivateUse1,
                "embedding_dense_grad_v2: pos_idx must be on NPU device");

    TORCH_CHECK(grad.scalar_type() == at::kFloat ||
                grad.scalar_type() == at::kHalf ||
                grad.scalar_type() == at::kBFloat16,
                "embedding_dense_grad_v2: only float32, float16, bfloat16 supported");

    // ---- Contiguous ----
    at::Tensor gradCont = grad.contiguous();
    at::Tensor sortIdxCont = sort_indices.contiguous();
    at::Tensor posIdxCont = pos_idx.contiguous();

    // ---- Dimension parameters ----
    int64_t ndim = gradCont.dim();
    int64_t embeddingDim = gradCont.size(ndim - 1);
    int64_t totalPositions = gradCont.numel() / embeddingDim;

    // Flatten grad to [totalPositions, embeddingDim]
    auto gradFlat = gradCont.reshape({totalPositions, embeddingDim});

    // Convert indices to int32
    auto sortIdxInt32 = sortIdxCont.to(at::kInt);
    auto posIdxInt32 = posIdxCont.to(at::kInt);

    // ---- Output tensor ----
    auto output = at::zeros({num_weights, embeddingDim}, gradCont.options());

    int64_t dtypeSize = gradCont.element_size();
    int64_t dtypeByte = dtypeSize;

    if (totalPositions == 0) return output;

    // ---- Platform info ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    if (coreNum < 1) coreNum = CORE_NUM;

    // ---- Block-level Tiling ----
    // Total positions processed across cores
    // Cache line alignment: each core's data should align to cache line
    // For position-level splitting (not byte-level), we use position counts

    // Each core gets an aligned number of positions
    // Cache line elements for int32 index: 512 / 4 = 128
    int64_t alignElements = CACHE_LINE_BYTES / sizeof(int32_t);  // 128

    int64_t totalLengthCore = (totalPositions + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = ((totalLengthCore + alignElements - 1) / alignElements) * alignElements;
    if (totalLengthCoreAlign < 1) totalLengthCoreAlign = 1;

    int64_t usedCoreNum = (totalPositions + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    int64_t tailNum = 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalPositions - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) {
        tailLength = 0;
        formerNum = usedCoreNum;
        tailNum = 0;
    }

    // ---- UB-level Tiling ----
    // UB allocation per position: 8 bytes (2 int32 indices)
    // Plus: embDimAligned * dtypeByte for grad row buffer
    int64_t embDimAligned = ((embeddingDim * dtypeByte + UB_ALIGN_BYTES - 1) / UB_ALIGN_BYTES)
                            * (UB_ALIGN_BYTES / dtypeByte);
    if (embDimAligned < 1) embDimAligned = 1;

    // Total per-position coefficient = 8 (index) + offset for single row
    // For fp32: rowBuf = embDimAligned * 4, total UB = tileLen * 8 + embDimAligned * 4
    // For fp16/bf16: rowBuf = embDimAligned * 2, total UB = tileLen * 8 + embDimAligned * 2

    int64_t rowBufBytes = embDimAligned * dtypeByte;
    int64_t maxTileElements = (static_cast<int64_t>(ubSize) - rowBufBytes) / INDEX_BUFFER_COEFF;
    if (maxTileElements < 8) maxTileElements = 8;

    // 32-byte alignment for int32: 8 elements
    int64_t alignTileElems = UB_ALIGN_BYTES / sizeof(int32_t);  // 8
    int64_t tileLength = (maxTileElements / alignTileElems) * alignTileElems;
    if (tileLength < 8) tileLength = 8;

    // ---- Launch Accumulate Kernel ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(embedding_dense_grad_v2_accumulate, blockDim,
                    gradFlat, sortIdxInt32, posIdxInt32, output,
                    totalPositions, embeddingDim, num_weights,
                    padding_idx, scale_grad_by_freq,
                    formerNum, formerLength, tailNum, tailLength,
                    tileLength, dtypeSize, embDimAligned, totalLengthCoreAlign);

    // ---- Launch Scale Kernel (if scale_grad_by_freq) ----
    if (scale_grad_by_freq != 0) {
        // Single-core scale kernel
        uint32_t scaleBlockDim = 1;
        int64_t scaleTileLength = tileLength;

        EXEC_KERNEL_CMD(embedding_dense_grad_v2_scale, scaleBlockDim,
                        output, sortIdxInt32,
                        totalPositions, embeddingDim, num_weights,
                        padding_idx, scaleTileLength, dtypeSize, embDimAligned);
    }

    return output;
}

}  // namespace ascend_kernel
